package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import android.content.Context;
import android.os.*;
import android.view.View;
import android.widget.*;
import java.util.concurrent.*;
public final class DataSourceStatusChecks{
 private static int checks;private interface Work{void run()throws Exception;}
 private static void ok(boolean b)throws Exception{if(!b)throw new Exception("来源状态断言失败");checks++;}
 private static void rejects(Work w)throws Exception{boolean failed=false;try{w.run();}catch(Exception e){failed=true;}ok(failed);}
 private static JSONObject base(String id)throws Exception{return new JSONObject().put("provider","sina-public").put("product","quote").put("granularity","snapshot").put("route","detail").put("target",new JSONObject().put("kind","instrument").put("id",id));}
 private static JSONObject packet(JSONArray records)throws Exception{return new JSONObject().put("schema","native-data-source-status/v1").put("records",records);}
 public static void main(String[] args)throws Exception{model();System.out.println("DataSourceStatus model PASS "+checks);}
 public static void model()throws Exception{JSONObject input=base("SH:stock:600000").put("acquisition","unavailable").put("cache","cached").put("fetchedAt","2026-10-12T02:00:00Z").put("attemptedAt","2026-10-13T02:00:00Z").put("authorizationVerified",true).put("sustainedRealtime",true).put("apiKey","sk-fixture-secret").put("rawResponse",new JSONObject().put("nestedKey","sk-fixture-secret")).put("error","Bearer sk-fixture-secret");JSONObject s=DataSourceStatusModel.snapshot(packet(new JSONArray().put(input))),r=s.getJSONArray("records").getJSONObject(0);ok(r.getString("authorization").equals("unknown"));ok(r.getString("sustainedRealtime").equals("unknown"));ok(r.getString("acquisition").equals("unavailable"));ok(r.getString("cache").equals("cached"));ok(r.isNull("sourceTime"));ok(r.getString("attemptedAt").equals("2026-10-13T02:00:00Z"));ok(!s.toString().contains("sk-fixture-secret"));ok(!DataSourceStatusModel.canOpen(r,Collections.emptyList()));ok(DataSourceStatusModel.canOpen(r,Arrays.asList("detail")));JSONObject sh=DataSourceStatusModel.snapshot(packet(new JSONArray().put(base("SH:index:000001")))),sz=DataSourceStatusModel.snapshot(packet(new JSONArray().put(base("SZ:stock:000001"))));ok(!sh.getJSONArray("records").getJSONObject(0).getString("key").equals(sz.getJSONArray("records").getJSONObject(0).getString("key")));ok(sz.getJSONArray("records").getJSONObject(0).getString("key").equals("f21d8a4dd85a1323dad85b1322c5ee989dcd0a1801fe77b716502693e52cd17e"));rejects(()->DataSourceStatusModel.snapshot(packet(new JSONArray().put(base("000001")))));rejects(()->DataSourceStatusModel.snapshot(packet(new JSONArray().put(input).put(input))));ok(DataSourceStatusModel.rows(s,new JSONObject().put("provider","missing")).length()==0);ok(DataSourceStatusModel.rows(s,new JSONObject().put("acquisition","unavailable")).length()==1);byte[] exported=DataSourceStatusModel.exportEvidence(s,new JSONObject());ok(!new String(exported,StandardCharsets.UTF_8).contains("sk-fixture-secret"));JSONObject noTime=DataSourceStatusModel.snapshot(packet(new JSONArray().put(base("SH:stock:600000").put("capability","observed-once").put("acquisition","available"))));ok(noTime.getJSONArray("records").getJSONObject(0).getString("capability").equals("unknown"));rejects(()->DataSourceStatusModel.snapshot(packet(new JSONArray().put(base("SH:stock:600000").put("sourceTime","sk-fixture-secret")))));}
 private static void mainThread(Work w)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){w.run();return;}CountDownLatch done=new CountDownLatch(1);Exception[] error={null};new Handler(Looper.getMainLooper()).post(()->{try{w.run();}catch(Exception e){error[0]=e;}finally{done.countDown();}});ok(done.await(20,TimeUnit.SECONDS));if(error[0]!=null)throw error[0];}
 public static void ui(Context c)throws Exception{mainThread(()->{final JSONObject[] target={null};DataSourceStatusScreen screen=new DataSourceStatusScreen(c,(route,t)->target[0]=t);screen.setSnapshot(packet(new JSONArray().put(base("SH:index:000001"))));Button open=screen.findViewWithTag("dataSourceOpen");ok(!open.isEnabled());screen.setAllowedRoutes(Arrays.asList("detail"));ok(open.isEnabled());open.performClick();ok(target[0].getString("id").equals("SH:index:000001"));ok(target[0].getString("granularity").equals("snapshot"));byte[] before=screen.exportEvidence();screen.setSnapshot(packet(new JSONArray().put(base("000001"))));JSONObject previous=new JSONObject(new String(before,StandardCharsets.UTF_8)),after=new JSONObject(new String(screen.exportEvidence(),StandardCharsets.UTF_8));ok(previous.getJSONArray("records").getJSONObject(0).getString("key").equals(after.getJSONArray("records").getJSONObject(0).getString("key")));screen.<EditText>findViewWithTag("dataSourceSearch").setText("sk-fixture-secret");ok(!screen.saveState().toString().contains("sk-fixture-secret"));screen.close();});}
 public static void geometry(Context c)throws Exception{mainThread(()->{DataSourceStatusScreen screen=new DataSourceStatusScreen(c,(route,t)->{});screen.setSnapshot(packet(new JSONArray().put(base("SH:stock:600000"))));float density=c.getResources().getDisplayMetrics().density;for(int[] size:new int[][]{{420,640},{840,190}}){screen.measure(View.MeasureSpec.makeMeasureSpec(Math.round(size[0]*density),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Math.round(size[1]*density),View.MeasureSpec.EXACTLY));screen.layout(0,0,screen.getMeasuredWidth(),screen.getMeasuredHeight());ok(((ScrollView)screen.getChildAt(2)).getMeasuredHeight()>Math.round(55*density));ok(screen.<Button>findViewWithTag("dataSourceOpen").getMeasuredHeight()>=Math.round(48*density));for(boolean dark:new boolean[]{false,true}){screen.setDarkTheme(dark);Button open=screen.findViewWithTag("dataSourceOpen");ok(open.getCurrentTextColor()!=open.getBackgroundTintList().getDefaultColor());}}screen.close();});}
}
